-- Casket Mimic dormant spawn points for gold-casket fail event
-- groupid=200 is free in every casket zone (observed max was 88).
-- spawntype=128 = event-only; respawntime=0 = no auto-respawn.
-- pos_y=-9999 places these out of the map; setPos() snaps them to
-- the failed chest position at spawn time.
--
-- Mob local_index 0x700: bit-11 clear so zoneutils::GetEntity decodes
-- the ID as (id & 0xFFF), matching the targid set at load time.

-- mob_groups: one row per zone (same groupid=200 is fine; PK is (zoneid,groupid))

-- mob_spawn_points: remove any old entries (wrong local_index 0xE00) then insert correct ones
DELETE FROM `mob_spawn_points` WHERE groupid=200 AND mobname='Casket_Mimic';

-- mob_spawn_points: one dormant entry per zone (local_index 0x700 = 1792)
-- mobid formula: 0x1000000 + (zoneId * 4096) + 0x700
